    function __ESBMC_assume(bool) internal pure {}
    function run(address target) public payable {
        require(target != address(c));
        uint dep0 = c.depositsCount(); if (__ESBMC_reverted()) return;
        c.sendMoney(target, 0); if (__ESBMC_reverted()) return;
        uint dep1 = c.depositsCount(); if (__ESBMC_reverted()) return;
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(!reverted && dep1 == dep0 && c.depositsCount() == dep0 && address(c).balance == 0);
    }
    receive() external payable {}
